$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('#login-form button');button.disabled=true;$('#login-error').textContent='Signing in…';const password=$('#password').value;$('#password').value='';try{signedIn(await api('/api/login',{method:'POST',headers:{'Content-Type':'application/json','X-Guard-Login':'1'},body:JSON.stringify({username:$('#username').value,password})}))}catch(e){$('#login-error').textContent=e.message}finally{button.disabled=false}});
$('#logout').addEventListener('click',async()=>{try{await api('/api/logout',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:'{}'});signIn('Signed out.')}catch(e){toast(e.message)}});
$('#theme').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;preference('guard-theme',theme);$('#theme').setAttribute('aria-label','Switch to '+(theme==='dark'?'light':'dark')+' theme')};
function setRail(collapsed,save=true){const focused=document.activeElement;$('#app').classList.toggle('collapsed',collapsed);if(save)preference('guard-rail',String(collapsed));$('#collapse').setAttribute('aria-expanded',String(!collapsed));$('#expand-sidebar').setAttribute('aria-expanded',String(!collapsed));$('#expand-sidebar').disabled=!collapsed;if(collapsed&&focused===$('#collapse'))$('#expand-sidebar').focus();if(!collapsed&&focused===$('#expand-sidebar'))$('#collapse').focus();$('#nav-tooltip').hidden=true}
$('#collapse').onclick=()=>setRail(true);
$('#expand-sidebar').onclick=()=>setRail(false);
setRail(preference('guard-rail')==='true',false);
$('#timezone-button').onclick=()=>{window.JagrataI18n.fillZones();openDialog($('#timezone-dialog'));$('#timezone-search').focus()};
document.addEventListener('click',event=>{if(event.target.closest('.timezone-open'))$('#timezone-button').onclick()});
$('#nav-dialog').addEventListener('click',event=>{if(event.target!==event.currentTarget)return;const r=event.currentTarget.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.currentTarget.close()});
const mobileQuery=matchMedia('(max-width:767px)');mobileQuery.addEventListener('change',()=>{if(!mobileQuery.matches&&$('#nav-dialog').open)$('#nav-dialog').close();$('#nav-tooltip').hidden=true});
function navTip(event){const button=event.target.closest('#nav button');if(!button||!$('#app').classList.contains('collapsed')||mobileQuery.matches)return;const tip=$('#nav-tooltip'),r=button.getBoundingClientRect();tip.textContent=button.getAttribute('aria-label');tip.style.left=`${r.right+10}px`;tip.style.top=`${r.top+r.height/2}px`;tip.hidden=false;button.setAttribute('aria-describedby','nav-tooltip')}
$('#nav').addEventListener('pointerover',navTip);$('#nav').addEventListener('focusin',navTip);
for(const event of ['pointerout','focusout'])$('#nav').addEventListener(event,()=>{$('#nav-tooltip').hidden=true;$$('#nav [aria-describedby]').forEach(b=>b.removeAttribute('aria-describedby'))});
document.addEventListener('keydown',event=>{if(event.key==='Escape')$('#nav-tooltip').hidden=true});
window.addEventListener('resize',()=>{$('#nav-tooltip').hidden=true});
$('#hamburger').onclick=()=>{openDialog($('#nav-dialog'));$('#hamburger').setAttribute('aria-expanded','true')};
function currentPage(){return location.hash.slice(1)||'overview'}
function navigation(){const page=currentPage();const html=pages.map(([id,icon,label])=>`<button data-page="${id}" aria-label="${label}" title="${label}" ${id===page?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span><span class="nav-label">${label}</span></button>`).join('');$('#nav').innerHTML=html;$('#mobile-nav').innerHTML=html;$('#crumb').textContent=pages.find(x=>x[0]===page)?.[2]||'Not found'}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){if($('#nav-dialog').open)$('#nav-dialog').close();location.hash=nav.dataset.page}const row=e.target.closest('[data-detail]');if(row)showDetail(Number(row.dataset.detail));if(e.target.closest('[data-retry]'))refresh()});
window.addEventListener('hashchange',()=>{if(currentPage()==='remediation')loadRemediation();render();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})});$('#refresh').onclick=()=>{refresh();loadRemediation();loadSecurity()};
function stale(){return snapshot&&(lastSuccess===0||Date.now()-lastSuccess>30000)}
function status(){if(!csrf)return;const fresh=stale()?'STALE':snapshot?.engine.freshness||'UNAVAILABLE';$('#status').innerHTML=`<span class="badge">Detection Only</span><span class="badge">${esc(fresh)}</span><span>${busy?'Reading engine…':snapshot?`Last observation ${esc(window.JagrataI18n.date(snapshot.observedAt))}`:'No successful engine observation'}</span>`}
async function refresh(){if(busy||!csrf||document.hidden)return;busy=true;error='';$('#refresh').disabled=true;if(!snapshot)loading();status();try{await loadSources();snapshot=await api('/api/snapshot');selected=new Set([...selected].filter(id=>snapshot.alerts?.some(a=>a.id===id)));lastSuccess=Date.now()}catch(e){error=e.status===401?'':e.message;if(snapshot)lastSuccess=0}finally{busy=false;$('#refresh').disabled=false;if(csrf)render()}}
function loading(){$('#content').innerHTML='<div class="heading"><div><h1>Reading the engine</h1><p>Retrieving bounded, read-only observations.</p></div></div><div class="skeleton-grid" aria-busy="true" aria-label="Loading engine observations"><div class="skeleton-block"></div><div class="skeleton-block"></div></div>'}
const heading=(name,description)=>`<div class="heading"><div><div class="eyebrow">LOCAL SECURITY / DETECTION ONLY</div><h1>${name}</h1><p>${description}</p></div></div>`;
const metric=(label,value,note,id='')=>`<div class="metric"><div class="metric-label">${label}</div><div data-number class="metric-value" ${id?`id="${id}"`:""}>${esc(value)}</div><small>${esc(note)}</small></div>`;
const panel=(title,content)=>`<section class="panel"><div class="panel-head"><h2>${title}</h2></div><div class="panel-body">${content}</div></section>`;
const when=value=>window.JagrataI18n.date(value);
function rows(alerts){return alerts.map(a=>`<tr><td><input type="checkbox" data-select="${a.id}" aria-label="Select alert ${a.id}" ${selected.has(a.id)?'checked':''}></td><td><button class="link row-title" data-detail="${a.id}">#${a.id} · ${esc(a.scenario.split('/').at(-1))}</button><span class="row-sub scenario" data-immutable>${esc(a.scenario)}</span></td><td data-label="Source"><code>${esc(a.source)}</code></td><td data-label="Detected">${esc(when(a.startedAt))}</td><td data-number data-label="Events">${a.eventCount}</td><td><span class="badge">HISTORICAL</span></td></tr>`).join('')}
function table(alerts){return alerts.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Data table region"><table><thead><tr><th scope="col">Select</th><th scope="col">Alert / scenario</th><th scope="col">Source</th><th scope="col">Detected at</th><th scope="col">Events</th><th scope="col">Evidence</th></tr></thead><tbody>${rows(alerts)}</tbody></table></div>`:'<div class="empty"><h2>No matching alerts</h2><p>No matching records in this bounded observation. This does not prove there were no attacks.</p></div>'}
function countBy(items,key){const counts=new Map();for(const a of items){const k=key(a);counts.set(k,(counts.get(k)||0)+1)}return [...counts].sort((a,b)=>String(a[0]).localeCompare(String(b[0])))}
function distribution(alerts){const counts=countBy(alerts,a=>a.scenario);const max=Math.max(1,...counts.map(x=>x[1]));return counts.length?'<div class="distribution">'+counts.map(([name,count])=>`<div class="distribution-row"><div class="distribution-label"><span class="scenario">${esc(name)}</span><strong data-number>${count}</strong></div><div class="distribution-track"><svg viewBox="0 0 100 7" preserveAspectRatio="none" aria-hidden="true"><rect width="${count/max*100}" height="7" fill="currentColor"/></svg></div></div>`).join('')+'</div>':'<p class="muted">No scenarios represented in the observed alert window.</p>'}
function activity(alerts){const counts=countBy(alerts.filter(a=>typeof a.startedAt==='string'&&/(Z|[+-]\d\d:\d\d)$/.test(a.startedAt)&&Number.isFinite(Date.parse(a.startedAt))),a=>new Date(a.startedAt).toISOString().slice(0,10)).slice(-7);const max=Math.max(1,...counts.map(x=>x[1]));return counts.length?'<div class="activity">'+counts.map(([day,count])=>`<div class="activity-day"><strong data-number>${count}</strong><svg viewBox="0 0 80 100" preserveAspectRatio="none" role="img" aria-label="${esc(day)}: ${count} alerts"><rect x="15" y="${100-count/max*90}" width="50" height="${count/max*90}" rx="3" fill="var(--accent)"/></svg><span>${esc(day)}</span></div>`).join('')+'</div>':'<p class="muted">No activity in this observation window.</p>'}
function overview(){const alerts=snapshot.alerts||[],known=snapshot.alerts!==null;return heading('Security Overview','Understand detection activity. Investigate the evidence before taking action.')+`<div class="metrics">${metric('ENGINE',snapshot.engine.state,'Observed process state')}${metric('LOCAL ALERT WINDOW',known?alerts.length:'Unknown',snapshot.window.truncated?'Partial · latest 200':'Bounded to latest 200')}${metric('SCENARIOS OBSERVED',known?new Set(alerts.map(a=>a.scenario)).size:'Unknown','Distinct in alert window')}${metric('ENFORCEMENT','Not managed','JAGRATA has no blocking controls')}</div><div class="grid">${panel('Detection activity · UTC dates',activity(alerts)+'<p class="chart-note">Limited observation window; bars show recorded counts, not a continuous traffic rate.</p>')}${panel('Scenario distribution',known?distribution(alerts):'<p class="muted">Alert observation unavailable.</p>')}</div><section class="panel"><div class="panel-head"><h2>Recent detections</h2><button class="link" data-page="alerts">Explore alerts →</button></div>${known?table(alerts.slice(0,5)):'<div class="panel-body">Stored alert observation unavailable. Counts are unknown.</div>'}</section>`}
function explorer(){if(snapshot.alerts===null)return heading('Alerts Explorer','Stored alert observation unavailable.')+'<div class="error-state"><h2>Alerts unavailable</h2><p>The engine is stopped or no authoritative alert read succeeded. Counts are unknown.</p><button data-retry>Retry observation</button></div>';const alerts=snapshot.alerts||[];const scenarios=[...new Set(alerts.map(a=>a.scenario))].sort();return heading('Alerts Explorer','Inspect authoritative local alert records. Severity is not inferred.')+`<div class="toolbar"><label>Search source, scenario or ID<input id="query" type="search" placeholder="Search evidence…" value="${esc(query)}"></label><label>Scenario<select id="scenario"><option value="">All scenarios</option>${scenarios.map(s=>`<option data-immutable value="${esc(s)}" ${s===scenario?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Sort<select id="order"><option value="newest" ${order==='newest'?'selected':''}>Newest detected</option><option value="oldest" ${order==='oldest'?'selected':''}>Oldest detected</option><option value="id" ${order==='id'?'selected':''}>Alert ID</option></select></label><label>Per page<select id="size">${[1,10,25,50].map(n=>`<option ${n===pageSize?'selected':''}>${n}</option>`).join('')}</select></label></div><button id="reset-filters" class="secondary">Reset filters</button><div id="alert-results"></div>`}
function resultRows(){const alerts=(snapshot.alerts||[]).filter(a=>(!scenario||scenario===a.scenario)&&`${a.source} ${a.scenario} #${a.id}`.toLowerCase().includes(query.toLowerCase()));alerts.sort((a,b)=>order==='id'?a.id-b.id:(Date.parse(a.startedAt)-Date.parse(b.startedAt)||a.id-b.id)*(order==='newest'?-1:1));const pages=Math.max(1,Math.ceil(alerts.length/pageSize));pageIndex=Math.min(pageIndex,pages-1);$('#alert-results').innerHTML=table(alerts.slice(pageIndex*pageSize,(pageIndex+1)*pageSize))+`<div class="pager"><span>${alerts.length} matching · ${selected.size} selected in observed window</span><button id="clear-selection" ${selected.size?'':'disabled'}>Clear selection</button><button id="prev" ${pageIndex?'':'disabled'}>Previous</button><span>Page ${pageIndex+1} of ${pages}</span><button id="next" ${pageIndex<pages-1?'':'disabled'}>Next</button></div>`;$('#prev').onclick=()=>{pageIndex--;resultRows()};$('#next').onclick=()=>{pageIndex++;resultRows()};$('#clear-selection').onclick=()=>{selected.clear();resultRows()}}
function bindExplorer(){$('#reset-filters').onclick=()=>{query='';scenario='';order='newest';pageIndex=0;render()};for(const id of ['query','scenario','order','size'])$('#'+id).addEventListener(id==='query'?'input':'change',()=>{query=$('#query').value;scenario=$('#scenario').value;order=$('#order').value;pageSize=Number($('#size').value);pageIndex=0;resultRows()});resultRows()}
document.addEventListener('change',e=>{if(e.target.matches('[data-select]')){const id=Number(e.target.dataset.select);e.target.checked?selected.add(id):selected.delete(id);if(currentPage()==='alerts')resultRows()}});
function counters(values){return '<div class="metric-list">'+Object.entries(values).map(([key,value])=>`<div><span>${esc(key)}</span><code data-number>${esc(value)}</code></div>`).join('')+'</div>'}
function metricSeries(name,values){return `<details class="metric-series"><summary><span class="mono">${esc(name)}</span><span class="summary-counters">${values.reads!==undefined?`<span data-number>${values.reads}</span> reads`:values.parsed!==undefined?`<span data-number>${values.parsed}</span> parsed`:''}</span></summary>${counters(values)}</details>`}
function health(){const m=snapshot.metrics;return heading('Engine Health','Process state and successful reads are observations, not guarantees of protection.')+`<div class="metrics">${metric('PROCESS',snapshot.engine.state,'Ownership verified')}${metric('LOCAL API',snapshot.engine.lapi?'Reachable':'Unknown','cscli alert read result')}${metric('OBSERVATION',stale()?'STALE':snapshot.engine.freshness,'Refresh manually','health-freshness')}${metric('SCENARIOS',snapshot.scenarios?.length??'Unknown','Enabled in installed hub')}</div>`+panel('Last engine observation',`<p>${esc(when(snapshot.observedAt))}</p><p class="muted">${snapshot.engine.lapi?'Stored alerts were retrieved from the engine. Their timestamps remain historical.':'No successful alert read. Current detection health cannot be established.'}</p>`)+(m?`<div class="grid">${panel('Acquisition counters','<p class="muted">Expand a series to inspect its counters. Cumulative counters do not establish recent log activity.</p>'+Object.entries(m.acquisition).map(([name,v])=>`${metricSeries(name,v)}`).join('')||'No acquisition counters returned.')}${panel('Scenario counters',Object.entries(m.scenarios).map(([name,v])=>`${metricSeries(name,v)}`).join('')||'No scenario counters returned.')}</div>`+panel('Parser observations',`<details><summary>${Object.keys(m.parsers).length} parser series · inspect counters</summary>${Object.entries(m.parsers).map(([name,v])=>`${metricSeries(name,v)}`).join('')}</details>`):'<div class="truth">Metrics unavailable. Source and parser health are unknown.</div>')+(snapshot.scenarios?panel('Installed scenarios',`<details><summary>${snapshot.scenarios.length} enabled scenarios</summary><ul>${snapshot.scenarios.map(s=>`<li class="mono">${esc(s)}</li>`).join('')}</ul></details>`):'')+advancedSecurityHealth()}
function sources(){
 const configured=sourceData?.sources.filter(s=>!s.removed)||[];
 return heading('Data Sources','Configure selected files. Verify parsing from engine evidence after an operator-approved deployment.')+`<div class="source-toolbar"><div><strong>${configured.length} configured sources</strong><p class="muted">Installation: <code>${esc(sourceData?.installationId||'Unavailable')}</code></p></div><button class="primary" id="source-add" ${sourceData?'':'disabled'}>+ Add source</button></div>`+(sourceFailure?`<div class="error-state" role="alert">${esc(sourceFailure)} <button id="source-retry">Retry sources</button></div>`:'')+(sourceData?`<div class="truth">${esc(brandCopy(sourceData.applyNotice))}</div>`:sourceFailure?'':'<div class="skeleton-block" aria-busy="true" aria-label="Loading sources"></div>')+(configured.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Data table region"><table class="source-table"><thead><tr><th>Source / file</th><th>Type / status</th><th>Processing evidence</th><th>Manage</th></tr></thead><tbody>${configured.map(s=>`<tr><td><strong data-immutable>${esc(s.name)}</strong><span class="row-sub mono">${esc(s.path)}</span><span class="row-sub mono">Container: ${esc(s.containerPath)}</span></td><td><span>${esc(sourceData.connectors[s.type].name)}</span><span class="row-sub"><span class="badge" data-source-status="${esc(s.status)}" data-observed-at="${esc(s.observedAt||'')}">${esc(s.status==='OBSERVED'&&(sourceFailure||Date.now()-Date.parse(s.observedAt)>30000)?'STALE':s.status)}</span></span></td><td>${s.counters?`<strong>${esc(s.counters.reads??'Unknown')} read / ${esc(s.counters.parsed??'Unknown')} parsed</strong><span class="row-sub">Cumulative; observed ${esc(when(s.observedAt))}</span>`:'<span class="muted">No recent evidence</span>'}${s.engineMayStillRead?'<p class="warning-text">Pending operator apply: engine retains a file mount.</p>':''}${s.validationError?`<p class="warning-text">${esc(s.validationError)}</p>`:''}<span class="row-sub">Last activity: unknown</span><details class="source-diagnostics"><summary>Parser diagnostics</summary><p class="muted">${esc(s.parserScope)}</p>${s.parserCounters?counters(s.parserCounters):'<p class="muted">Parser counters unavailable.</p>'}</details>${s.alertIds.length?`<span class="row-sub">Associated alert IDs: ${s.alertIds.map(id=>`<button class="link" data-detail="${id}">#${id}</button>`).join(' ')}</span>`:''}</td><td><div class="source-actions"><button data-source-edit="${s.id}">Edit</button><button data-source-disable="${s.id}" ${s.enabled?'':'disabled'}>Disable</button><button data-source-remove="${s.id}">Remove</button></div></td></tr>`).join('')}</tbody></table></div>`:sourceData?'<div class="empty source-empty"><h2>No configured sources</h2><p>Add one SSH authentication or Nginx access log file. JAGRATA does not discover private logs.</p></div>':'')+'<div class="truth registry-notice">This list contains only JAGRATA-managed registrations. Engine acquisition counters may include independently configured paths. An empty list does not mean acquisition failed; no engine source has been adopted or changed.</div>'+panel('Apply and verify',`<ol class="setup-steps"><li>Select a single local file and validate its path. Validation does not read its contents or prove its format.</li><li>Save a draft. Ask the local operator to generate and review a source deployment plan using the source setup guide.</li><li>The operator approves any new mounts or engine interruption. This Console never starts or restarts Docker.</li><li>Append authorized test events after the source is active, refresh, and inspect per-file read/parsed counters. Counters are cumulative; parser totals are engine-wide.</li></ol><p class="muted">Supported: syslog SSH authentication and Nginx combined access logs. Apache, Docker logs, journald, syslog server and Windows Event Logs are not implemented. A Windows path needs an explicit Docker Desktop mount.</p>`)+(sourceData?.sources.some(s=>s.removed&&s.engineMayStillRead)?'<div class="truth warning-text">A removed configuration is still mounted in the current engine. Removal is pending an explicit operator deployment; existing log files are preserved.</div>':'');
}
async function loadSources(){try{sourceData=await api('/api/sources');sourceFailure=''}catch(e){sourceFailure=e.message}}
function bindSources(){
 $('#source-add')?.addEventListener('click',()=>sourceDrawer());
 $('#source-retry')?.addEventListener('click',async()=>{await loadSources();render()});
 $$('[data-source-edit]').forEach(b=>b.onclick=()=>sourceDrawer(sourceData.sources.find(s=>s.id===b.dataset.sourceEdit)));
 $$('[data-source-disable]').forEach(b=>b.onclick=()=>confirmSource('disable',b.dataset.sourceDisable));
 $$('[data-source-remove]').forEach(b=>b.onclick=()=>confirmSource('remove',b.dataset.sourceRemove));
}
const sourcePost=(path,data)=>api(path,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(data)});
function sourceDrawer(source){
 const revision=sourceData.revision,d=$('#source-drawer');d.innerHTML=`<div class="dialog-head"><h2 id="source-title">${source?'Edit source':'Add source'}</h2><button data-close aria-label="Close source configuration">×</button></div><form id="source-form" class="source-form"><p class="muted">One explicitly selected file. Saving creates configuration only.</p><label>Display name<input name="name" required maxlength="80" value="${esc(source?.name||'')}" autofocus></label><label>Source type<select name="type">${Object.entries(sourceData.connectors).map(([key,c])=>`<option value="${key}" ${source?.type===key?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div id="source-format" class="truth"></div><label>Absolute local file path<input name="path" required maxlength="1024" placeholder="C:/logs/auth.log or /var/log/auth.log" value="${esc(source?.path||'')}"></label><p class="muted">Paste an exact file path. No directory browsing, wildcard imports or log-content upload. Docker sees a different container path.</p><label class="check-label"><input type="checkbox" name="enabled" ${!source||source.enabled?'checked':''}> Include in the next approved deployment</label><label class="check-label"><input type="checkbox" name="consent" required> I authorize JAGRATA to inspect this selected file's metadata and prepare read-only engine access.</label><details><summary>Parser and deployment details</summary><dl id="source-parser"></dl><p class="muted">Log files can contain personal data. JAGRATA does not copy file contents. Single-file bind mounts do not follow rotation to a new inode; review mounts after rotation.</p></details><div id="source-feedback" role="status" aria-live="polite"></div><div class="form-actions"><button type="button" id="source-validate">Validate path</button><button class="primary" type="submit">Save configuration</button></div></form>`;
 const form=$('#source-form'),format=()=>{const c=sourceData.connectors[form.elements.type.value];$('#source-format').textContent=c.format;$('#source-parser').innerHTML=`<dt>Collection</dt><dd class="mono">${esc(c.collection)}</dd><dt>Parser</dt><dd class="mono">${esc(c.parser)}</dd><dt>Type label</dt><dd class="mono">${esc(c.label)}</dd><dt>Installation</dt><dd class="mono">${esc(sourceData.installationId)}</dd>`};format();form.elements.type.onchange=format;
 const value=()=>({name:form.elements.name.value,type:form.elements.type.value,path:form.elements.path.value,enabled:form.elements.enabled.checked,consent:form.elements.consent.checked});
 const perform=async(save)=>{if(sourcePending||!form.reportValidity())return;sourcePending=true;const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);$('#source-feedback').textContent=save?'Saving configuration...':'Validating selected path...';try{if(save){sourceData=await sourcePost('/api/sources/save',{revision,...(source?{id:source.id}:{}),source:value()});render();d.close();toast('Source configuration saved. Engine access is pending operator approval.')}else{const result=await sourcePost('/api/sources/validate',value());$('#source-feedback').textContent=result.message;toast('Local file validated. Ingestion is not yet verified.')}}catch(e){$('#source-feedback').textContent=e.message;toast(e.message)}finally{sourcePending=false;buttons.forEach(b=>b.disabled=false)}};
 form.onsubmit=e=>{e.preventDefault();perform(true)};$('#source-validate').onclick=()=>perform(false);openDialog(d);
}
function confirmSource(action,id){
 const revision=sourceData.revision,source=sourceData.sources.find(s=>s.id===id),d=$('#source-confirm');d.innerHTML=`<div class="dialog-head"><h2 id="source-confirm-title">${action==='remove'?'Remove configuration':'Disable source'}?</h2><button data-close aria-label="Cancel source action">×</button></div><div class="detail-body"><p><strong data-immutable>${esc(source.name)}</strong></p><p>Only the saved configuration changes. The file is preserved. A running engine can continue reading until an operator applies the removal.</p><p id="source-confirm-error" role="alert"></p><div class="form-actions"><button data-close>Cancel</button><button class="primary" id="source-confirm-action">Confirm ${action}</button></div></div>`;openDialog(d);$('#source-confirm-action').onclick=async()=>{if(sourcePending)return;sourcePending=true;const b=$('#source-confirm-action');b.disabled=true;b.textContent='Saving...';try{sourceData=action==='remove'?await sourcePost('/api/sources/remove',{revision,id,confirm:true}):await sourcePost('/api/sources/save',{revision,id,source:{name:source.name,type:source.type,path:source.path,enabled:false,consent:true}});render();d.close();toast(action==='remove'?'Configuration removed. Engine removal requires operator apply.':'Source disabled in configuration. Operator apply is pending.')}catch(e){$('#source-confirm-error').textContent=e.message;b.disabled=false;b.textContent='Retry'}finally{sourcePending=false}};
}

function render(){if(!csrf)return;$('#content').dataset.page=currentPage();navigation();status();if(!pages.some(p=>p[0]===currentPage())){$('#content').innerHTML=heading('404 · Workspace not found','Choose a page from the navigation.');return}if(currentPage()==='security'){$('#content').innerHTML=securityView();bindSecurity();return}if(currentPage()==='sources'){$('#content').innerHTML=sources();bindSources();return}if(currentPage()==='remediation'){$('#content').innerHTML=remediationView();bindRemediation();return}if(!snapshot){if(busy){loading();return}$('#content').innerHTML=heading('Engine unavailable','No sample data has been substituted.')+`<div class="error-state"><h2>Unable to read CrowdSec</h2><p>${esc(error||'Refresh to request an observation from the configured engine.')}</p><button data-retry>Retry observation</button></div>`;return}const notices=[...snapshot.warnings];if(error)notices.unshift('Refresh failed. Previously observed data is retained and STALE. '+error);if(stale())notices.unshift('STALE observation. Refresh before interpreting engine health.');$('#content').innerHTML=(notices.length?`<div class="truth notice" role="status">${notices.map(esc).join('<br>')}</div>`:'')+({overview,alerts:explorer,health,sources}[currentPage()]())+`<div class="truth">${esc(snapshot.window.description)} ${snapshot.window.truncated?'Additional records exist beyond this window.':''} Alert times describe stored evidence; LIVE describes a successful current read. JAGRATA does not create decisions or enforce blocks. External enforcement has not been audited.</div>`;if(currentPage()==='alerts'&&$('#alert-results'))bindExplorer();if(currentPage()==='health')bindSecurity()}
async function showDetail(id){const d=$('#detail');d.innerHTML='<div class="dialog-head"><h2 id="detail-title">Alert #'+id+'</h2><button data-close aria-label="Close alert">✕</button></div><div class="detail-body"><div class="skeleton-block" aria-busy="true" aria-label="Loading alert"></div></div>';openDialog(d);const generation=++detailGeneration;try{const data=await api('/api/alerts/'+id);if(generation!==detailGeneration||!d.open)return;detail(data.alert,'evidence')}catch(e){if(generation===detailGeneration&&d.open)d.querySelector('.detail-body').innerHTML=`<h3>Evidence unavailable</h3><p>${esc(e.message)}</p><button id="detail-retry">Retry</button>`;$('#detail-retry')?.addEventListener('click',()=>showDetail(id))}}
function detail(a,tab){const d=$('#detail');d.innerHTML=`<div class="dialog-head"><h2 id="detail-title">Alert #${a.id}</h2><button data-close aria-label="Close alert">✕</button></div><div class="detail-tabs" role="tablist" aria-label="Alert detail">${['evidence','metadata','context'].map(t=>`<button role="tab" data-tab="${t}" id="tab-${t}" aria-controls="detail-panel" tabindex="${tab===t?0:-1}" aria-selected="${tab===t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><section class="detail-body" id="detail-panel" role="tabpanel" aria-labelledby="tab-${tab}" tabindex="0"><span class="badge">HISTORICAL EVIDENCE</span><h3 class="scenario">${esc(a.scenario)}</h3>${tab==='evidence'?`<dl><dt>Source ${esc(a.scope)}</dt><dd><code id="source-ip">${esc(a.source)}</code></dd><dt>Detected</dt><dd>${esc(when(a.startedAt))}</dd><dt>Alert events</dt><dd>${a.eventCount}</dd><dt>Scenario version</dt><dd>${esc(a.scenarioVersion||'Unavailable')}</dd></dl><button class="secondary" id="copy">Copy Source IP</button><h3>Available event evidence</h3><p class="muted">Showing ${a.events.length} returned events, capped at 100. Metadata uses a server allowlist.</p>${a.events.map((e,i)=>`<details class="evidence-event"><summary>Event ${i+1} · ${esc(when(e.timestamp))}</summary><dl>${Object.entries(e.meta).map(([k,v])=>`<dt>${esc(k)}</dt><dd class="mono">${esc(v)}</dd>`).join('')}</dl></details>`).join('')}`:tab==='metadata'?`<p class="muted">Normalized allowlisted record; no engine credentials or raw configuration.</p><pre>${esc(JSON.stringify(a,null,2))}</pre>`:`<h3>Detection, decision, enforcement</h3><p>This alert records detected behavior. ${a.decisions.length} decision record(s) were returned. A decision record does not prove that traffic was blocked.</p><h3>Stored decisions</h3>${a.decisions.map(v=>`<p><code>${esc(v.type)}</code> · stored duration ${esc(v.duration||'unavailable')} (not a live countdown)</p>`).join('')||'<p>No decisions returned.</p>'}<div class="truth">JAGRATA is read only. Decision changes and network enforcement are disabled. Local protection policy is managed in Remediation Center. External enforcement status is unverified.</div>`}</section>`;portal();$$('#detail [data-tab]').forEach(b=>{b.onclick=()=>{detail(a,b.dataset.tab);$('#tab-'+b.dataset.tab).focus()};b.onkeydown=e=>{const tabs=['evidence','metadata','context'];if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?2:(tabs.indexOf(tab)+(e.key==='ArrowRight'?1:2))%3;detail(a,tabs[next]);$('#tab-'+tabs[next]).focus()}}});$('#copy')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(a.source);toast('Copied '+a.source+' to clipboard.')}catch{toast('Copy failed. Select the source IP and copy it manually.')}})}
setInterval(()=>{if(!document.hidden&&csrf&&snapshot){status();$$('[data-source-status=OBSERVED]').forEach(b=>{if(sourceFailure||Date.now()-Date.parse(b.dataset.observedAt)>30000)b.textContent='STALE'});const field=$('#health-freshness');if(field)field.textContent=stale()?'STALE':snapshot.engine.freshness}},5000);
setInterval(()=>{const field=$('#decision-freshness');if(field&&decisionData)field.textContent=Date.now()-Date.parse(decisionData.observedAt)>30000?'STALE':'OBSERVED'},5000);
async function loadRemediation(){
 if(!csrf)return;const generation=++remediationGeneration;remediationBusy=true;remediationFailure='';decisionFailure='';if(currentPage()==='remediation')render();
 const result=await Promise.allSettled([api('/api/remediation'),api('/api/remediation/decisions')]);
 if(generation!==remediationGeneration||!csrf)return;remediationBusy=false;
 if(result[0].status==='fulfilled')remediationData=result[0].value;else{remediationData=null;remediationFailure=result[0].reason.message}
 if(result[1].status==='fulfilled')decisionData=result[1].value;else{decisionData=null;decisionFailure=result[1].reason.message}
 if(currentPage()==='remediation')render();
}
function remediationView(){
 const data=remediationData,decisions=decisionData?.records;
 return heading('Remediation Center','Review internal decisions and manage local safeguards. No automatic blocking.')+
 `<div class="truth"><strong>Detection → Internal decision → Enforcement</strong><p>Alerts describe suspicious behavior. Decisions are internal records. Enforcement: <strong>NOT VERIFIED</strong>. No enforcement adapter is enabled.</p></div>`+
 (remediationBusy?'<div class="skeleton-block" aria-busy="true" aria-label="Loading remediation observations"></div>':'')+
 (remediationFailure?`<div class="error-state" role="alert">Local policy unavailable: ${esc(remediationFailure)}</div>`:'')+
 (decisionFailure?`<div class="error-state" role="alert">Decisions unavailable: ${esc(decisionFailure)}. No zero count or sample data substituted.</div>`:'')+
 `<div class="source-toolbar"><p>Installation: <code>${esc(data?.installationId||decisionData?.installationId||'Unavailable')}</code></p><button id="remediation-refresh" ${remediationBusy?'disabled':''}>Refresh observations</button></div>`+
 (decisionData?`<section class="panel"><div class="panel-head"><h2>Internal decisions</h2><span class="badge" id="decision-freshness">${Date.now()-Date.parse(decisionData.observedAt)>30000?'STALE':'OBSERVED'}</span></div><div class="panel-body"><p class="muted">Observed ${esc(when(decisionData.observedAt))}. ${esc(decisionData.note)}</p></div>${decisions.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Data table region"><table class="remediation-table"><thead><tr><th>Decision / target</th><th>Origin / scenario</th><th>Status / time</th><th>Enforcement</th></tr></thead><tbody>${decisions.map(d=>`<tr><td><strong data-immutable>#${d.id} · ${esc(d.type)}</strong><span class="row-sub mono">${esc(d.scope)}: ${esc(d.target)}</span><button class="link" data-detail="${d.alertId}">Alert #${d.alertId}</button></td><td><span data-immutable>${esc(d.origin)}</span><span class="row-sub scenario">${esc(d.scenario)}</span><span class="row-sub">${d.guardOwned?'JAGRATA owned':'Not JAGRATA owned'}</span></td><td>${esc(d.status)}<span class="row-sub">Remaining at observation: ${esc(d.duration)}</span><span class="row-sub">Estimated expiry: ${esc(when(d.estimatedExpiresAt))}</span><span class="row-sub">Decision creation time: unknown</span><span class="row-sub">Alert created: ${esc(when(d.alertCreatedAt))}</span></td><td><span class="badge">NOT VERIFIED</span><p class="muted">No verified network block</p><button data-revoke-preview="${d.id}" ${data?'':'disabled'}>Preview reversal</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No decision records returned in this bounded read. Stored alerts may remain.</div>'}</section>`:'')+
 (data?`<div class="remediation-tools"><section class="panel"><div class="panel-head"><h2>Local protection allowlist</h2><button id="allowlist-add" class="primary">Add protection</button></div><div class="panel-body"><p class="muted">${esc(brandCopy(data.notice))}</p><p>Revision ${data.revision}. Public management IPs and critical infrastructure must be registered explicitly.</p><details><summary>Built-in protected ranges</summary><p class="mono">${data.builtins.map(esc).join(' · ')}</p></details>${data.entries.filter(e=>e.active).map(e=>`<div class="protection-entry"><div><strong class="mono">${esc(e.target)}</strong><p data-immutable>${esc(e.reason)}</p><small>JAGRATA action <code>${esc(e.actionId)}</code></small></div><button data-policy-rollback="${esc(e.actionId)}">Preview rollback</button></div>`).join('')||'<p>No additional local protections. Built-in local and private ranges remain protected.</p>'}</div></section>`+
 panel('Dry-run action preview',`<p>Propose an internal decision for one IP. Protected targets are rejected. Public ownership remains unverified. Applying a decision is unavailable in this release.</p><form id="decision-preview-form" class="remediation-form"><label>Exact IP<input name="target" required maxlength="64" placeholder="203.0.113.164" autocomplete="off"></label><button type="submit">Preview only</button></form>`)+
 '</div>'+panel('Audit trail',`<p class="muted">Showing the latest ${data.audit.length} of ${data.auditCount} retained records. Capacity 2,000; actions stop when full. Local hash chain detects accidental alteration, not tampering by the host administrator.</p><div class="audit-list" tabindex="0" aria-label="Audit trail">${data.audit.map(a=>`<details><summary>${esc(a.action)} · ${esc(a.result)}</summary><dl><dt>Actor</dt><dd data-immutable>${esc(a.actor)}</dd><dt>Time</dt><dd>${esc(when(a.at))}</dd><dt>Target</dt><dd class="mono">${esc(a.target)}</dd><dt>Correlation ID</dt><dd class="mono">${esc(a.correlationId)}</dd>${a.reverses?`<dt>Reverses</dt><dd class="mono">${esc(a.reverses)}</dd>`:''}</dl></details>`).join('')||'<p>No recorded actions.</p>'}</div>`):'');
}
function bindRemediation(){
 $('#remediation-refresh').onclick=()=>loadRemediation();
 $('#allowlist-add')?.addEventListener('click',()=>{const d=$('#remediation-dialog');d.innerHTML=`<div class="dialog-head"><h2 id="remediation-title">Add local protection</h2><button data-close aria-label="Cancel protection">Close</button></div><form id="protection-form" class="source-form"><p>Protect an administrator endpoint, infrastructure address or management CIDR in JAGRATA. This does not synchronize a CrowdSec allowlist.</p><label>IP or canonical network CIDR<input name="target" required maxlength="64" autocomplete="off" autofocus></label><label>Reason / asset<input name="reason" required maxlength="160"></label><p id="remediation-error" role="alert"></p><div class="form-actions"><button type="button" data-close>Cancel</button><button type="submit" class="primary">Review protection</button></div></form>`;openDialog(d);$('#protection-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;await remediationPreview({action:'allowlist.add',target:f.elements.target.value,reason:f.elements.reason.value})}});
 $('#decision-preview-form')?.addEventListener('submit',e=>{e.preventDefault();remediationPreview({action:'decision.create',target:e.currentTarget.elements.target.value})});
 $$('[data-policy-rollback]').forEach(b=>b.onclick=()=>remediationPreview({action:'rollback',actionId:b.dataset.policyRollback}));
 $$('[data-revoke-preview]').forEach(b=>b.onclick=()=>{const d=decisionData.records.find(d=>d.id===Number(b.dataset.revokePreview));remediationPreview({action:'decision.revoke',target:d.target,decisionId:d.id})});
}
let remediationActionPending=false;
async function remediationPreview(value){
 if(remediationActionPending)return;remediationActionPending=true;const actionSession=csrf;
 try{const p=await sourcePost('/api/remediation/preview',value);if(!csrf||csrf!==actionSession)return;const d=$('#remediation-dialog');d.innerHTML=`<div class="dialog-head"><h2 id="remediation-title">${p.executable?'Confirm local policy':'Dry-run only'}</h2><button data-close aria-label="Close preview">Close</button></div><div class="detail-body"><dl><dt>Installation</dt><dd class="mono">${esc(remediationData.installationId)}</dd><dt>Operation</dt><dd>${esc(p.action)}</dd><dt>Exact target</dt><dd class="mono">${esc(p.target)}</dd><dt>Correlation ID</dt><dd class="mono">${esc(p.correlationId)}</dd><dt>Expires</dt><dd>${esc(when(p.expiresAt))}</dd></dl><h3>Exact proposed operation</h3><pre>${esc(JSON.stringify(p.proposed,null,2))}</pre><h3>Expected effect</h3><p>${esc(brandCopy(p.effect))}</p><h3>Risks and limitations</h3><ul>${p.risks.map(r=>`<li>${esc(brandCopy(r))}</li>`).join('')}</ul>${p.executable?`<form id="remediation-confirm-form"><label>Type <code>${esc(p.confirmation)}</code><input name="confirmation" required autocomplete="off" maxlength="64"></label><p id="remediation-error" role="alert"></p><button type="submit" class="primary" id="remediation-confirm">Confirm local policy change</button></form>`:'<div class="truth">Decision changes and network enforcement are disabled. Preview is recorded; no decision or firewall action occurred.</div>'}</div>`;openDialog(d);portal();(d.querySelector('input')||d.querySelector('[data-close]'))?.focus();if(p.executable)$('#remediation-confirm-form').onsubmit=async e=>{e.preventDefault();if(remediationActionPending)return;const f=e.currentTarget;remediationActionPending=true;$('#remediation-confirm').disabled=true;try{const result=await sourcePost('/api/remediation/confirm',{correlationId:p.correlationId,confirmation:f.elements.confirmation.value});if(!result.ok)throw Error(result.result+'. Refresh and create a new preview.');d.close();toast('Local policy saved. No engine or network change.');await loadRemediation()}catch(error){if($('#remediation-error'))$('#remediation-error').textContent=error.message+' No automatic retry. Refresh policy and audit before trying again.'}finally{remediationActionPending=false;if($('#remediation-confirm'))$('#remediation-confirm').disabled=false}};void loadRemediation()}
 catch(e){toast(e.message);if($('#remediation-error'))$('#remediation-error').textContent=e.message}
 finally{remediationActionPending=false}
}
