/* Security workspace */
// Shared on-demand observations. No new polling loop or activation endpoint.
let securityData=null,securityError='',securityBusy=false;
async function loadSecurity(){if(!csrf||securityBusy||document.hidden)return;securityBusy=true;const session=csrf;try{const value=await api('/api/security');if(csrf!==session)return;securityData=value;securityError=''}catch{if(csrf===session)securityError='Security observations unavailable. Existing detections remain read-only.'}finally{securityBusy=false;if(csrf===session&&['health','security'].includes(currentPage())&&!document.querySelector('dialog[open]')&&!document.activeElement?.closest('form'))render()}}
const securityNumber=v=>v===null||v===undefined?'Unknown':Number.isFinite(v)?String(Math.round(v*1000000)/1000000):'Unknown';
const securityState=value=>({AVAILABLE:'Available',PARTIAL:'Partial observation',UNKNOWN:'Unknown',UNAVAILABLE:'Unavailable',DISABLED:'Disabled',BLOCKLIST_DISABLED:'Blocklist disabled',CONFIGURED_NOT_VERIFIED:'Configured, not verified',NOT_CONFIGURED:'Not configured',RULES_INSTALLED:'Rules installed',CONFIGURATION_PRESENT:'Configuration present',NOT_VERIFIED:'Not verified',UPGRADE_REQUIRED:'Upgrade required',APPROVAL_REQUIRED:'Operator approval required',WARMING_UP:'Awaiting second sample',OBSERVED_ACTIVITY:'Counter increase observed',IDLE:'No counter increase',COUNTER_RESET:'Counter reset',CLOCK_SKEW:'Clock skew',RECENT_PULL:'Recent API pull',STALE_PULL:'Older API pull',NEVER_OBSERVED:'No API pull observed',REGISTERED:'Registered',REVOKED:'Revoked'}[value]||value||'Unknown');
const securityValue=value=>value===true?'Enabled':value===false?'Disabled':'Unknown';
function nativeSecurityMetrics(metrics){const rows=[];function walk(value,path){if(rows.length>=200)return;if(typeof value==='number'){rows.push(`<div><code>${esc(path)}</code><strong data-number>${securityNumber(value)}</strong></div>`);return}if(value&&typeof value==='object')for(const [k,v]of Object.entries(value))walk(v,path?path+'/'+k:k)}walk(metrics,'');return rows.length?`<details><summary>Native counters</summary><div class="metric-list">${rows.join('')}</div><p class="muted">Cumulative component-reported values. They do not prove end-to-end enforcement.</p></details>`:'<p class="muted">No metric series observed. No zero values substituted.</p>'}
function advancedSecurityHealth(){
 const d=securityData;if(!d?.identity)return panel('Advanced engine observation',`<p class="muted">${esc(securityError||'Read a shared, bounded observation to inspect capabilities.')}</p><button data-security-refresh ${securityBusy?'disabled':''}>Read security observation</button>`);
 const i=d.identity,rows=(d.sources||[]).map(s=>`<tr><td><code>${esc(s.source)}</code><span class="row-sub">${s.managed===null?'Registry unknown':s.managed?'JAGRATA-managed':'Engine configuration; not adopted'}</span></td><td data-label="Read" data-number>${securityNumber(s.reads)}</td><td data-label="Parsed" data-number>${securityNumber(s.parsed)}</td><td data-label="Unparsed" data-number>${securityNumber(s.unparsed)}</td><td data-label="Read rate / second" data-number>${securityNumber(s.readsPerSecond)}</td><td>${esc(securityState(s.state))}<span class="row-sub">Counter increase observed at: ${esc(s.counterIncreaseObservedAt?when(s.counterIncreaseObservedAt):'Unknown')}</span></td></tr>`).join('');
 return panel('Advanced engine observation',`<div class="security-summary"><dl><dt>Engine display name</dt><dd data-security-copy>JAGRATA engine</dd><dt>Engine version</dt><dd class="mono">${esc(d.engineVersion?.version||'Unknown')}</dd><dt>Actual container name</dt><dd class="mono">${esc(i.name)}</dd><dt>Immutable container ID</dt><dd class="mono">${esc(i.id)}</dd><dt>Official image provenance</dt><dd class="mono">${esc(i.imageReference)}<br>${esc(i.imageId)}</dd><dt>Process start</dt><dd data-security-copy>${esc(when(i.startedAt))}</dd><dt>Uptime seconds</dt><dd data-number>${securityNumber(i.uptimeSeconds)}</dd><dt>Restart count</dt><dd data-number>${securityNumber(i.restartCount)}</dd><dt>Observation time</dt><dd data-security-copy>${esc(when(d.observedAt))}</dd></dl><div><span class="badge">${esc(securityState(d.state))}</span><p class="muted">One owned engine, multiple log sources. Identity is verified at observation time.</p><p class="muted">Rates require two same-process samples. Idle counters do not prove that a source is healthy.</p><p class="muted">${d.restarted?'Engine restart observed; rates reset.':'No restart observed between retained samples.'}</p><button data-security-refresh ${securityBusy?'disabled':''}>Read security observation</button></div></div>`)+panel('Configured sources and observed ingestion',`<p class="muted">Configured acquisition paths are distinct from JAGRATA-managed registrations. Missing counters remain unknown; no source is silently adopted.</p>${rows?`<div class="table-wrap" tabindex="0" role="region" aria-label="Source observation table"><table><thead><tr><th>Source</th><th>Read</th><th>Parsed</th><th>Unparsed</th><th>Read rate / second</th><th>Observation</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<p>No acquisition series or inspected file definitions available.</p>'}<p class="muted">Last event timestamp and active-tail proof are unavailable from these counters.</p>`);
}
function securityInventory(){const d=securityData;if(!d?.inventory)return '';return panel('Installed Hub and engine capabilities',`<p class="muted">Inventory observed ${esc(when(d.inventoryObservedAt))}. Cached for five minutes; no Hub update or installation is performed.</p><div class="security-inventory">${Object.entries(d.inventory.hub||{}).map(([kind,items])=>{const installed=(items||[]).filter(x=>x.installed);return `<details><summary><span data-immutable>${esc(kind)}</span> · <span data-number>${installed.length}</span></summary><ul>${installed.slice(0,100).map(x=>`<li><code>${esc(x.name)}</code> <span class="mono">${esc(x.version)}</span></li>`).join('')}</ul></details>`}).join('')}</div><details><summary>Compiled optional components</summary><ul>${(d.engineVersion?.components||[]).map(c=>`<li><code>${esc(c)}</code></li>`).join('')}</ul><p class="muted">Compiled support does not prove host access or an active datasource.</p></details><details><summary>Log processors and simulation</summary><div class="table-wrap" tabindex="0" role="region" aria-label="Log processor inventory"><table><thead><tr><th>Log processor</th><th>Version</th><th>Last heartbeat</th><th>Last alert push</th></tr></thead><tbody>${(d.inventory.machines||[]).map(m=>`<tr><td class="mono">${esc(m.id)}</td><td class="mono">${esc(m.version)}</td><td>${esc(m.lastHeartbeat?when(m.lastHeartbeat):'Unknown')}</td><td>${esc(m.lastPush?when(m.lastPush):'Unknown')}</td></tr>`).join('')}</tbody></table></div><p>Simulation: ${securityValue(d.inventory.config?.simulation?.enabled)}</p><p class="muted">Profile names are configuration inventory only; notification delivery is not verified.</p><ul>${(d.inventory.profiles||[]).map(x=>`<li class="mono">${esc(x)}</li>`).join('')}</ul></details><details><summary>Actual engine allowlists</summary><p class="muted">Engine allowlists are separate from JAGRATA-local protection policy. No synchronization is enabled.</p>${d.inventory.allowlists===null?'<p>Engine allowlist inventory unavailable.</p>':(d.inventory.allowlists||[]).length?d.inventory.allowlists.map(a=>`<div class="truth"><strong data-immutable>${esc(a.name)}</strong><p>${a.consoleManaged?'Console managed':'Locally managed'}</p><ul>${a.items.slice(0,100).map(i=>`<li><code>${esc(i.value)}</code> · ${esc(i.expiresAt?when(i.expiresAt):'No expiry reported')}</li>`).join('')}</ul></div>`).join(''):'<p>No engine allowlists returned.</p>'}</details>`)}
function communitySecurity(){const c=securityData?.community;if(!c)return '';return panel('Community Blocklist',`<span class="badge">${esc(securityState(c.state))}</span><dl><dt>Local CAPI credentials present</dt><dd data-security-copy>${securityValue(c.credentialsPresent)}</dd><dt>Outbound sharing configuration</dt><dd data-security-copy>${securityValue(c.sharing)}</dd><dt>Community pull configuration</dt><dd data-security-copy>${securityValue(c.pull)}</dd><dt>Service reachability</dt><dd data-security-copy>Not probed; external access requires approval.</dd><dt>Subscription eligibility</dt><dd data-security-copy>Unknown; no entitlement request made.</dd><dt>Last successful synchronization</dt><dd data-security-copy>${esc(c.lastSuccessfulSync?when(c.lastSuccessfulSync):'Unknown')}</dd><dt>Community-origin decisions in bounded observation</dt><dd data-number>${c.decisions===null?'Unknown':c.decisions.length}</dd></dl><details><summary>Privacy and external services</summary><p>CAPI and Console may exchange detection IPs, scenarios, timestamps, engine metadata and optional context. Review sharing settings and service terms before registration.</p><p>Credentials on disk do not prove remote enrollment, an active subscription or feed redistribution rights.</p><p>Stored sharing preferences do not mean sharing is active when CAPI is disabled.</p><dl>${Object.entries(c.privacy||{}).map(([k,v])=>`<dt class="mono">${esc(k)}</dt><dd data-security-copy>${securityValue(v)}</dd>`).join('')}</dl><p>Authoritative CAPI last-pull/error instrumentation is missing from official v1.8.1. No sync time is invented.</p></details><button data-plan-kind="community">Prepare review plan</button>`)}
function appsecSecurity(){const a=securityData?.appsec;if(!a)return '';return panel('AppSec and WAF',`<span class="badge">${esc(securityState(a.state))}</span><dl><dt>Engine compatibility</dt><dd data-security-copy>${esc(securityState(a.compatibility))}</dd><dt>Installed AppSec rules</dt><dd data-number>${securityNumber(a.rulesInstalled)}</dd><dt>Installed AppSec configurations</dt><dd data-number>${securityNumber(a.configsInstalled)}</dd><dt>AppSec acquisition</dt><dd data-security-copy>${securityValue(a.acquisitionConfigured)}</dd><dt>Request forwarding</dt><dd data-security-copy>Not verified</dd><dt>Network enforcement</dt><dd data-security-copy>Not verified</dd></dl><p class="muted">Rules installed, requests inspected and traffic blocked are separate evidence stages. A bouncer API pull does not prove forwarding.</p>${a.listeners.length?`<ul>${a.listeners.map(x=>`<li class="mono">${esc(x||'Unknown')}</li>`).join('')}</ul>`:''}${nativeSecurityMetrics(a.metrics)}<details><summary>Cumulative AppSec latency</summary><p class="muted">Mean seconds from native histogram sums/counts, when available. No percentile or current latency is invented.</p>${nativeSecurityMetrics(securityData.extras?.latency)}</details><button data-plan-kind="appsec-nginx">Prepare Nginx AppSec plan</button>`)}
function bouncerSecurity(){const bs=securityData?.bouncers;return panel('Remediation components',`<p class="muted">Registration and last API pull are observations, not proof of enforcement. Docker CrowdSec does not automatically protect the Windows host or LAN.</p>${bs===null||bs===undefined?'<p>Bouncer observation unavailable.</p>':!bs.length?'<p>No registered remediation components returned.</p>':`<div class="table-wrap" tabindex="0" role="region" aria-label="Remediation component inventory"><table><thead><tr><th>Component</th><th>Type / version</th><th>Last API pull</th><th>Observation</th><th>Enforcement</th></tr></thead><tbody>${bs.map(b=>`<tr><td data-immutable>${esc(b.name)}</td><td class="mono">${esc(b.type)} / ${esc(b.version)}</td><td>${esc(b.lastPull?when(b.lastPull):'Unknown')}</td><td>${esc(securityState(b.freshness))}</td><td>Not verified</td></tr>`).join('')}</tbody></table></div>`}<p class="muted">Recent means within two minutes of the sample; this is not a configured SLA or live connectivity test.</p>${nativeSecurityMetrics(securityData?.metrics?.bouncers)}<button data-plan-kind="bouncer-nginx">Prepare component review plan</button>`)}
function capabilitySecurity(){const cs=securityData?.capabilities||[];return panel('Upstream capability coverage',`<p class="muted">Compatibility and integration availability do not mean a capability is enabled. Master-only native changes need an audited stable release or separately reviewed backport.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Capability matrix"><table><thead><tr><th>Capability</th><th>Audited engine baseline</th><th>Integration state</th><th>Dependency</th></tr></thead><tbody>${cs.map(c=>`<tr><td><code>${esc(c.id)}</code><span class="row-sub">${esc(c.purpose)}</span></td><td class="mono">${c.minimumAuditedVersion||'master / application layer'}</td><td>${esc(securityState(c.state))}</td><td>${esc(c.dependency)}</td></tr>`).join('')}</tbody></table></div>`)}
function securityView(){const d=securityData;return heading('Security Integrations','Shared engine evidence, optional community intelligence and approval-controlled protection workflows.')+`<div class="truth">Integration plans do not enable CAPI, intercept requests, register components or apply decisions.</div>${securityError?`<p role="alert">${esc(securityError)}</p>`:''}${!d?.identity?`<div class="panel panel-body"><p>Security observation unavailable. No sample data substituted.</p><button data-security-refresh ${securityBusy?'disabled':''}>Read security observation</button></div>`:`<p class="muted"><span>Observed</span> ${esc(when(d.observedAt))}. <span>Shared refresh is limited to one sample per 30 seconds.</span></p><div class="security-cards">${communitySecurity()}${appsecSecurity()}${bouncerSecurity()}</div>${securityInventory()}${capabilitySecurity()}${securityPlanForm()}`}`}
function securityPlanForm(){return panel('Operator review workspace',`<p>Prepare a bounded plan. Activation needs a separate exact operator approval outside this browser.</p><form id="security-plan-form" class="security-plan-form"><label>Integration<select name="kind"><option value="community">Community Blocklist</option><option value="appsec-nginx">AppSec and WAF</option><option value="bouncer-nginx">Remediation components</option><option value="decision-create">Internal decision</option><option value="engine-allowlist">Actual engine allowlists</option><option value="notifications">Notifications</option><option value="hub-update">Hub update</option><option value="simulation">Simulation</option><option value="datasource">Additional datasource</option><option value="engine-upgrade">Engine upgrade compatibility</option></select></label><label>Exact target IP / CIDR<input name="target" maxlength="64" placeholder="203.0.113.164"></label><label>Reason<input name="reason" maxlength="100"></label><label>Duration in minutes<input name="minutes" type="number" min="1" max="1440" value="15"></label><label>Protected management CIDRs<input name="management" maxlength="1024" placeholder="198.51.100.0/24"></label><label>Failure mode<select name="failMode"><option value="fail-open">Fail open</option><option value="fail-closed">Fail closed</option></select></label><label>Datasource family<select name="sourceType">${['file','syslog','journalctl','docker','http','kubernetes','kubernetesaudit','s3','cloudwatch','kinesis','kafka','loki','victorialogs','wineventlog'].map(t=>`<option data-immutable>${t}</option>`).join('')}</select></label><label class="check-label"><input type="checkbox" required> I understand this prepares a plan only and does not authorize activation.</label><p id="security-plan-error" role="alert"></p><button class="primary" type="submit">Prepare review plan</button></form>`)}
function bindSecurity(){
 $$('[data-security-refresh]').forEach(b=>b.onclick=()=>loadSecurity());
 $$('[data-plan-kind]').forEach(b=>b.onclick=()=>{const f=$('#security-plan-form');if(f){f.elements.kind.value=b.dataset.planKind;f.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});f.elements.kind.focus()}});
 const f=$('#security-plan-form');if(!f)return;f.onsubmit=async event=>{event.preventDefault();const button=f.querySelector('[type=submit]');if(button.disabled)return;button.disabled=true;$('#security-plan-error').textContent='';try{const key=[...crypto.getRandomValues(new Uint8Array(16))].map(x=>x.toString(16).padStart(2,'0')).join('');const value={kind:f.elements.kind.value,target:f.elements.target.value.trim(),reason:f.elements.reason.value,minutes:Number(f.elements.minutes.value),managementCidrs:f.elements.management.value.split(',').map(s=>s.trim()).filter(Boolean),proxy:'nginx',failMode:f.elements.failMode.value,sourceType:f.elements.sourceType.value,sharing:false,idempotencyKey:key};const p=await sourcePost('/api/security/plan',value);const d=$('#security-plan-dialog');d.innerHTML=`<div class="dialog-head"><h2 id="security-plan-title">Operator approval required</h2><button data-close aria-label="Close review plan">Close</button></div><div class="detail-body"><p>This plan has not been applied. No activation endpoint is available in the Console.</p><dl><dt>Created</dt><dd data-security-copy>${esc(when(p.createdAt))}</dd><dt>Expires</dt><dd data-security-copy>${esc(when(p.expiresAt))}</dd><dt>Exact review phrase</dt><dd data-security-copy><code>${esc(p.confirmation)}</code></dd></dl><p>Keep this receipt for separate operator review. It contains no API key.</p><pre tabindex="0">${esc(JSON.stringify(p,null,2))}</pre></div>`;openDialog(d);d.querySelector('[data-close]').focus()}catch(e){$('#security-plan-error').textContent=e.message}finally{button.disabled=false}};
}
